    @Test
    public void testNullValue_DeferredNameNotNull_SerializeNullsTrue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new Writer() {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public void write(String s) throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public void write(char[] cbuf) throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public void flush() throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public void close() throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public void write(int c) throws IOException {
                fail("Not expected to be called");
            }

            @Override
            public boolean append(char c) throws IOException {
                fail("Not expected to be called");
                return false;
            }

            @Override
            public void write(String s, int off, int len) throws IOException {
                fail("Not expected to be called");
            }
        });
        jsonWriter.deferredName = "deferred";
        jsonWriter.serializeNulls = true;
        jsonWriter.nullValue();
        assertFalse(jsonWriter.deferredName == null);
    }

